<body><div class="app-shell"><?php require __DIR__.'/include/sidebar.php'; ?><main class="main-stage"><?php require __DIR__.'/include/topbar.php'; ?><section class="page-content"><script src="assets/js/toaster.js"></script><script src="assets/js/app.js"></script><script src="assets/js/theme.js"></script><script src="assets/js/layout.js"></script><script src="assets/js/validation.js"></script><script src="assets/js/global-select.js"></script><script src="assets/js/aqua-tax-mode.js"></script>
<div class="page-heading"><div><h1 id="heading">Customer Order</h1><p>Order confirmation does not reduce stock. Delivery status updates only from actual customer delivery.</p></div><div class="heading-actions"><span class="pill pending" id="taxBadge" hidden>NON GST</span><a class="btn gray" href="order-list.php"><i data-lucide="list"></i>Order List</a></div></div>
